select t.task_id, t.task_name, t.task_type, t.region_id, r.region_name, t.target_count, case when t.task_type = 'questionnaire' then ( select count(*) from gc_questionnaire_record qr join gc_resident res on qr.resident_id = res.resident_id join gc_region reg on (reg.region_id = t.region_id or reg.parent_id = t.region_id) and (res.district = reg.region_name or res.street = reg.region_name) where qr.create_time between t.start_time and t.end_time ) when t.task_type = 'blood' then ( select count(*) from gc_resident res join gc_region reg on (reg.region_id = t.region_id or reg.parent_id = t.region_id) and (res.district = reg.region_name or res.street = reg.region_name) where res.sampling_status = '1' and res.create_time between t.start_time and t.end_time ) else 0 end as completed_count, case when t.target_count > 0 then round( case when t.task_type = 'questionnaire' then ( select count(*) from gc_questionnaire_record qr join gc_resident res on qr.resident_id = res.resident_id join gc_region reg on (reg.region_id = t.region_id or reg.parent_id = t.region_id) and (res.district = reg.region_name or res.street = reg.region_name) where qr.create_time between t.start_time and t.end_time ) when t.task_type = 'blood' then ( select count(*) from gc_resident res join gc_region reg on (reg.region_id = t.region_id or reg.parent_id = t.region_id) and (res.district = reg.region_name or res.street = reg.region_name) where res.sampling_status = '1' and res.create_time between t.start_time and t.end_time ) else 0 end * 100.0 / t.target_count, 2 ) else 0 end as completion_rate, t.status from gc_task t left join gc_region r on t.region_id = r.region_id
AND t.task_type = #{taskType}
AND t.region_id = #{regionId}
AND t.status = #{status}
order by t.create_time desc

select t.task_id, t.task_name, t.task_type, t.region_id, r.region_name, t.target_count, case when t.task_type = 'questionnaire' then ( select count(*) from gc_questionnaire_record qr join gc_resident res on qr.resident_id = res.resident_id join gc_region reg on reg.region_id in ( select region_id from gc_region where region_id = #{regionId} or parent_id = #{regionId} ) and (res.district = reg.region_name or res.street = reg.region_name) where qr.create_time between t.start_time and t.end_time ) when t.task_type = 'blood' then ( select count(*) from gc_resident res join gc_region reg on reg.region_id in ( select region_id from gc_region where region_id = #{regionId} or parent_id = #{regionId} ) and (res.district = reg.region_name or res.street = reg.region_name) where res.sampling_status = '1' and res.create_time between t.start_time and t.end_time ) else 0 end as completed_count, case when t.target_count > 0 then round( case when t.task_type = 'questionnaire' then ( select count(*) from gc_questionnaire_record qr join gc_resident res on qr.resident_id = res.resident_id join gc_region reg on reg.region_id in ( select region_id from gc_region where region_id = #{regionId} or parent_id = #{regionId} ) and (res.district = reg.region_name or res.street = reg.region_name) where qr.create_time between t.start_time and t.end_time ) when t.task_type = 'blood' then ( select count(*) from gc_resident res join gc_region reg on reg.region_id in ( select region_id from gc_region where region_id = #{regionId} or parent_id = #{regionId} ) and (res.district = reg.region_name or res.street = reg.region_name) where res.sampling_status = '1' and res.create_time between t.start_time and t.end_time ) else 0 end * 100.0 / t.target_count, 2 ) else 0 end as completion_rate, t.status from gc_task t left join gc_region r on t.region_id = r.region_id where t.region_id in ( select region_id from gc_region where region_id = #{regionId} or parent_id = #{regionId} )
AND t.task_type = #{taskType}
order by t.create_time desc
